+    }
+
+    /** JSONB 컬럼 원문을 맵으로. NULL 이면 빈 맵 — 없는 키는 부른 쪽이 만들지 않는다. */
+    static Map<String, Object> json(String raw) {
+        if (raw == null) {
+            return Map.of();
+        }
+        try {
+            return JSON.readValue(raw, MAP);
+        } catch (IOException e) {
+            throw new UncheckedIOException(e);
+        }
+    }
